import { Component, OnInit } from '@angular/core';
import { forkJoin } from 'rxjs';
import { BankAccount } from '../../core/interfaces/bank-account';
import { CartItem } from '../../core/interfaces/cart-item';
import { BankService } from '../../core/services/bank.service';
import { CartService } from '../../core/services/cart.service';

@Component({
  selector: 'app-cart',
  templateUrl: './cart.component.html',
  styleUrls: ['./cart.component.css']
})
export class CartComponent implements OnInit {
  showSuccessModal = false;
  cartItems: CartItem[] = [];
  account: BankAccount | null = null;
  loading = false;
  paying = false;
  errorMessage = '';
  successMessage = '';

  paymentForm = {
    fullName: 'Your Name',
    email: 'customer@pizzeria.com',
    address: '17 Burgundy Street',
    cardNumber: '4242424242424242',
    expiry: '12/28',
    cvv: '123'
  };

  constructor(
    private readonly cartService: CartService,
    private readonly bankService: BankService
  ) {}

  ngOnInit(): void {
    this.refreshData();
  }

  refreshData(): void {
    this.loading = true;
    this.errorMessage = '';

    forkJoin({
      cart: this.cartService.getCart(),
      account: this.bankService.getAccount()
    }).subscribe({
      next: ({ cart, account }) => {
        this.cartItems = cart;
        this.account = account;
        this.loading = false;
      },
      error: (error: Error) => {
        this.loading = false;
        this.errorMessage = error.message;
      }
    });
  }

  increase(item: CartItem): void {
    this.updateQuantity(item, item.quantity + 1);
  }

  decrease(item: CartItem): void {
    if (item.quantity === 1) {
      this.remove(item);
      return;
    }
    this.updateQuantity(item, item.quantity - 1);
  }

  remove(item: CartItem): void {
    this.errorMessage = '';
    this.successMessage = '';
    this.cartService.removeItem(item.id).subscribe({
      next: (response) => {
        this.successMessage = response.message;
        this.refreshData();
      },
      error: (error: Error) => {
        this.errorMessage = error.message;
      }
    });
  }

  payNow(): void {
    this.errorMessage = '';
    this.successMessage = '';

    if (this.cartTotal <= 0) {
      this.errorMessage = 'Your cart is empty.';
      return;
    }

    this.paying = true;

    this.bankService
      .charge({
        ...this.paymentForm,
        amount: this.cartTotal
      })
      .subscribe({
        next: (response) => {
          this.cartService.clearCart().subscribe({
            next: () => {
              this.paying = false;
             this.showSuccessModal = true;
              this.refreshData();
            },
            error: (clearError: Error) => {
              this.paying = false;
              this.errorMessage = clearError.message;
              this.refreshData();
            }
          });
        },
        error: (error: Error) => {
          this.paying = false;
          this.errorMessage = error.message;
        }
      });
  }

  get cartTotal(): number {
    return this.cartItems.reduce((sum, item) => sum + item.unitPrice * item.quantity, 0);
  }

  private updateQuantity(item: CartItem, quantity: number): void {
    this.errorMessage = '';
    this.successMessage = '';

    this.cartService.updateQuantity(item.id, quantity).subscribe({
      next: () => {
        this.successMessage = 'Cart updated.';
        this.refreshData();
      },
      error: (error: Error) => {
        this.errorMessage = error.message;
      }
    });
  }
  
  closeModal(): void {
    this.showSuccessModal = false;
  }
}


<section class="container cart-page">
  <div class="cart-header">
    <div>
      <h1 class="section-title">Order Summary & Payment</h1>
      <p class="section-subtitle">
        Quantity updates, item removal, bank balance refresh, and payment submission all go through API requests.
      </p>
    </div>
    <button class="btn btn-secondary" type="button" (click)="refreshData()">
      {{ loading ? 'Refreshing...' : 'Refresh cart & bank' }}
    </button>
  </div>

  @if (errorMessage) {
    <div class="message error">{{ errorMessage }}</div>
  }

  @if (successMessage) {
    <div class="message success">{{ successMessage }}</div>
  }

  <div class="cart-layout">
    <section class="card cart-items-panel">
      <h2>Cart items</h2>

      @if (cartItems.length === 0 && !loading) {
        <div class="empty-state">Your cart is empty. Add a customized pizza from the menu.</div>
      }

      <div class="item-list">
        @for (item of cartItems; track item.id) {
          <article class="cart-item">
            <div class="item-main">
              <div class="item-icon">{{ item.imageEmoji }}</div>
              <div>
                <h3>{{ item.pizzaName }}</h3>
                <p>{{ item.size | titlecase }} · {{ item.crust | titlecase }}</p>
                <div class="ingredients">
                  @for (ingredient of item.ingredients; track ingredient.id) {
                    <span>{{ ingredient.name }}</span>
                  }
                </div>
              </div>
            </div>

            <div class="item-actions">
              <div class="quantity-box">
                <button class="qty-btn" type="button" (click)="decrease(item)">−</button>
                <span>{{ item.quantity }}</span>
                <button class="qty-btn" type="button" (click)="increase(item)">+</button>
              </div>
              <strong>${{ (item.unitPrice * item.quantity).toFixed(2) }}</strong>
              <button class="btn btn-danger" type="button" (click)="remove(item)">Remove</button>
            </div>
          </article>
        }
      </div>
    </section>

    <section class="card checkout-panel">
      <div class="account-box">
        <h2>Bank account</h2>
        @if (account) {
          <p><strong>Holder:</strong> {{ account.holder }}</p>
          <p><strong>Balance:</strong> ${{ account.balance.toFixed(2) }} {{ account.currency }}</p>
          <p><strong>Card:</strong> **** **** **** {{ account.last4 }}</p>
        }
      </div>

      <div class="summary-box">
        <div>
          <span>Order total</span>
          <strong>${{ cartTotal.toFixed(2) }}</strong>
        </div>
      </div>

      <form class="checkout-form" (ngSubmit)="payNow()">
        <div class="form-group">
          <label for="fullName">Full name</label>
          <input id="fullName" class="input" name="fullName" [(ngModel)]="paymentForm.fullName" required />
        </div>

        <div class="form-group">
          <label for="email">Email</label>
          <input id="email" class="input" type="email" name="email" [(ngModel)]="paymentForm.email" required />
        </div>

        <div class="form-group">
          <label for="address">Delivery address</label>
          <input id="address" class="input" name="address" [(ngModel)]="paymentForm.address" required />
        </div>

        <div class="form-group">
          <label for="cardNumber">Card number</label>
          <input id="cardNumber" class="input" name="cardNumber" [(ngModel)]="paymentForm.cardNumber" required />
        </div>

        <div class="inline-grid">
          <div class="form-group">
            <label for="expiry">Expiry</label>
            <input id="expiry" class="input" name="expiry" [(ngModel)]="paymentForm.expiry" required />
          </div>

          <div class="form-group">
            <label for="cvv">CVV</label>
            <input id="cvv" class="input" name="cvv" [(ngModel)]="paymentForm.cvv" required />
          </div>
        </div>

        <button class="btn btn-primary pay-btn" type="submit" [disabled]="paying">
          {{ paying ? 'Processing payment...' : 'Pay now' }}
        </button>
      </form>
    </section>
  </div>
</section>

@if (showSuccessModal) {
  <div class="modal-overlay">
    <div class="modal-content success-card">
      <div class="mascot-container">
        <img src="assets/pmaskotlogin.jpg" alt="Success Mascot" class="success-mascot">
      </div>
      <h2 class="success-title">Payment Successful!</h2>
      <p>Your pizza is being prepared and will arrive soon.</p>
      <button class="btn btn-primary" (click)="closeModal()">Awesome!</button>
    </div>
  </div>
}
